<template><div class="agent-chain" aria-live="polite"><template v-for="(node,index) in nodes" :key="node.title"><article class="agent-node" :class="state(index)" :style="{animationDelay:`${index*90}ms`}"><div class="icon"><component :is="node.icon" /></div><strong>{{node.title}}</strong><span>{{node.summary}}</span><small>{{stateLabel(index)}}</small></article><div v-if="index<nodes.length-1" class="connector">→</div></template></div></template>
<script setup lang="ts">import{computed}from'vue';interface NodeItem{title:string;summary:string;icon:any}const props=defineProps<{nodes:NodeItem[];activeIndex:number;running:boolean}>();const nodes=computed(()=>props.nodes);function state(index:number){if(props.running&&index===props.activeIndex)return'processing';if(!props.running&&props.activeIndex>=nodes.value.length)return'completed';if(index<props.activeIndex)return'completed';return'idle'}function stateLabel(index:number){const current=state(index);return current==='processing'?'处理中':current==='completed'?'已完成':'待处理'}</script>
<style scoped>.agent-chain{display:flex;align-items:stretch;margin-top:22px;overflow-x:auto;padding-bottom:8px}.agent-node{width:154px;min-width:154px;min-height:150px;border:1px solid #cbdadd;border-top:4px solid #aabcc1;padding:15px 12px;display:flex;flex-direction:column;align-items:center;text-align:center;transition:border-color .25s,box-shadow .25s;animation:node-in .38s both}.agent-node.completed{border-top-color:#2c7a55}.agent-node.processing{border-top-color:#167692;box-shadow:0 0 0 4px rgba(22,118,146,.12);animation:pulse 1.05s ease-in-out infinite}.agent-node .icon{width:38px;height:38px;color:#146c85}.agent-node .icon :deep(svg){width:100%;height:100%}.agent-node strong{margin-top:8px;font-size:17px}.agent-node span{font-size:13px;color:#63727a;line-height:1.4;margin-top:7px}.agent-node small{margin-top:auto;color:#63727a}.agent-node.completed small{color:#2c7a55}.agent-node.processing small{color:#167692;font-weight:700}.connector{display:grid;place-items:center;width:28px;min-width:28px;font-size:22px;color:#72909a}@keyframes node-in{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}@keyframes pulse{50%{transform:translateY(-3px)}}@media(max-width:800px){.agent-chain{flex-direction:column}.agent-node{width:auto;min-width:0}.connector{height:28px;width:100%;transform:rotate(90deg)}}</style>
